#[inductive(client_recv)]
fn client_recv_inductive(pre: Self, post: Self, j: nat) {
    // Facts from the transition (client j went from Waiting to Idle, slot j became false)
    assert(post.clients.index(j)->Idle);
    assert(!post.slots.index(j));

    // Prove not_waiting_inv holds in post state
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && match post.clients.index(i) { Client::Idle => true, _ => false } ==> 
        !post.slots.index(i)) by {
        if i == j {
            // client j is now Idle and its slot is false
            assert(!post.slots.index(j));
        } else {
            // client i != j is unchanged 
            assert(post.clients.index(i) === pre.clients.index(i));
            assert(post.slots.index(i) === pre.slots.index(i));
            // Apply the inductive hypothesis: pre satisfies not_waiting_inv
            assert(pre.valid_idx(i) && match pre.clients.index(i) { Client::Idle => true, _ => false } ==> !pre.slots.index(i));
            // If i was Idle in pre, then its slot was false in pre, hence false in post
        }  
    };

    // Prove waiting_inv holds in post state
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==> 
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
}

